// Desktop deviation: the web file links the Google Fonts CDN stylesheets. The
// desktop app makes no font CDN request, so the same families are bundled under
// public/fonts/google/ (generated by scripts/fetch-google-fonts.mjs) and linked
// locally. The world sheet (CJK, ~113 MB) is not bundled; those families render
// with a fallback.
const FONT_STYLESHEETS: Array<{ id: string; href: string }> = [
  { id: "studio-fonts-stylesheet", href: "/fonts/google/studio.css" },
  { id: "curated-fonts-stylesheet", href: "/fonts/google/curated.css" },
  { id: "indic-fonts-stylesheet", href: "/fonts/google/indic.css" },
];

let injected = false;

const appendStylesheet = (id: string, href: string): void => {
  if (document.getElementById(id)) return;
  const link = document.createElement("link");
  link.id = id;
  link.rel = "stylesheet";
  link.href = href;
  document.head.appendChild(link);
};

export const ensureStudioFontsLoaded = (): void => {
  if (injected || typeof document === "undefined") return;
  FONT_STYLESHEETS.forEach((sheet) => appendStylesheet(sheet.id, sheet.href));
  injected = true;
};
